package com.fixflow.mall.service;

import com.fixflow.mall.domain.MallUser;
import com.fixflow.mall.repo.UserRepository;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.Mockito;
import org.mockito.junit.jupiter.MockitoExtension;

import java.util.Optional;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.mockito.Mockito.when;

@ExtendWith(MockitoExtension.class)
public class UserServiceTest {

    @Mock
    private UserRepository userRepository;

    @InjectMocks
    private UserService userService;

    @Test
    @DisplayName("正向测试：当 profileJson 格式正确时，返回正确的 nickname")
    void testGetNickname_Success() {
        Long userId = 1L;
        MallUser mockUser = Mockito.mock(MallUser.class);
        when(mockUser.getProfileJson()).thenReturn("key:value");
        when(userRepository.findById(userId)).thenReturn(Optional.of(mockUser));

        String nickname = userService.getNickname(userId);

        assertEquals("value", nickname);
    }

    @Test
    @DisplayName("边界测试：当 profileJson 为 null 时，返回 null 而不抛出异常")
    void testGetNickname_ProfileJsonNull() {
        Long userId = 1L;
        MallUser mockUser = Mockito.mock(MallUser.class);
        when(mockUser.getProfileJson()).thenReturn(null);
        when(userRepository.findById(userId)).thenReturn(Optional.of(mockUser));

        String nickname = userService.getNickname(userId);

        assertNull(nickname);
    }
}
